<script setup lang="ts">
usePageMeta('我的纸笺','在当前访客会话中继续草稿，查看投稿状态和学习进度。',true)
const tab=ref('works')
const {data:works,pending,error,refresh}=await useFetch<any[]>('/api/me/works',{server:false})
const {data:progress,error:progressError,refresh:retryProgress}=await useFetch<any[]>('/api/me/progress',{server:false})
const {data:favorites,error:favoriteError,refresh:retryFavorites}=await useFetch<any[]>('/api/me/favorites',{server:false})
const labels:Record<string,string>={draft:'未完的心意',pending:'等待展馆审核',published:'已经在展览中',rejected:'请修改后再投稿'}
</script>
<template><div class="wrap page"><Breadcrumbs :items="[{label:'我的纸笺'}]"/><header class="page-heading split-heading"><div><p class="eyebrow">YOUR LITTLE PAPER COLLECTION</p><h1>心意，妥帖收好。</h1><p>在这台浏览器里，接着上一次的创作。</p></div><NuxtLink class="btn primary" to="/studio">铺开一张新纸 ↗</NuxtLink></header><p class="session-note">以当前浏览器的访客身份保存。清除 Cookie、更换浏览器或 90 天会话到期后，无法继续读取私人纸笺。下载图像可保留作品外观。</p><div class="filter-tabs me-tabs" aria-label="纸笺分类"><button v-for="[key,label] in [['works','草稿与投稿'],['progress','学习足迹'],['favorites','收藏的灵感']]" :key="key" :class="{selected:tab===key}" @click="tab=key!">{{label}}</button></div><AsyncState v-if="tab==='works'" :pending="pending" :error="error" :empty="!works?.length" @retry="refresh"><div class="draft-grid"><article v-for="w in works" :key="w.id"><WorkCard :work="w" private-work/><div class="draft-state"><span>{{labels[w.status]}}</span><NuxtLink v-if="w.status==='published'" :to="`/gallery/${w.id}`" class="text-link">看看展览 ↗</NuxtLink><small v-else>第 {{w.version}} 版</small></div><p v-if="w.review_note" class="review-note">展馆留言：{{w.review_note}}</p></article></div></AsyncState><AsyncState v-else-if="tab==='progress'" :error="progressError" :empty="!progress?.length" @retry="retryProgress"><div class="progress-list"><article v-for="p in progress" :key="p.tutorial_id"><div><p class="eyebrow">{{p.step>=p.total?'已经完成':'正在生长'}} / {{p.step}} of {{p.total}}</p><h2>{{p.title}}</h2><progress :value="p.step" :max="p.total" :aria-label="p.title+'完成进度'"/></div><NuxtLink class="text-link" :to="`/studio?tutorial=${p.slug}`">{{p.step>=p.total?'再练一次':'继续这段练习'}} ↗</NuxtLink></article></div></AsyncState><AsyncState v-else :error="favoriteError" :empty="!favorites?.length" @retry="retryFavorites"><div class="works-grid"><WorkCard v-for="w in favorites" :key="w.id" :work="w"/></div></AsyncState></div></template>
